-- 시드 데이터: 카테고리·상품 (가격은 디바이스마트 판매가 기준)
insert into public.categories (slug, name, description, image, sort_order)
select slug, name, description, image, sort_order
from jsonb_to_recordset($json$[{"slug":"boards","name":"아두이노 보드","description":"아두이노 정품·호환 보드와 ESP32 개발보드","image":"/images/categories/boards.jpg","sort_order":1},{"slug":"sensors","name":"센서","description":"거리, 온습도, 인체감지, 토양 습도, 기울기 센서 모듈","image":"/images/categories/sensors.jpg","sort_order":2},{"slug":"actuators","name":"모터·액추에이터","description":"서보·스텝모터, 릴레이, 모터 드라이버","image":"/images/categories/actuators.jpg","sort_order":3},{"slug":"displays","name":"디스플레이","description":"문자 LCD, OLED, LED 도트 매트릭스","image":"/images/categories/displays.jpg","sort_order":4},{"slug":"parts","name":"부품·공구","description":"브레드보드, 점퍼 케이블, LED, 저항 등 기초 부품","image":"/images/categories/parts.jpg","sort_order":5},{"slug":"kits","name":"키트","description":"처음 시작하는 사람을 위한 아두이노 학습 키트","image":"/images/categories/kits.jpg","sort_order":6}]$json$::jsonb)
  as c(slug text, name text, description text, image text, sort_order int)
on conflict (slug) do update set name = excluded.name, description = excluded.description,
  image = excluded.image, sort_order = excluded.sort_order;

insert into public.products (category_id, slug, name, brand, summary, description, price, stock, specs, image, source_url, is_featured)
select c.id, p.slug, p.name, p.brand, p.summary, p.description, p.price, p.stock, p.specs, p.image, p.source_url, p.is_featured
from jsonb_to_recordset($json$[{"category":"boards","slug":"arduino-uno-r3","name":"아두이노 우노 R3 (정품)","brand":"Arduino","summary":"ATmega328P 기반의 대표 아두이노 입문 보드","description":"아두이노 공식 정품 UNO R3(A000066)입니다. ATmega328P를 사용하며 디지털 I/O 14핀, 아날로그 입력 6핀을 제공합니다. 대부분의 아두이노 예제와 쉴드가 이 보드를 기준으로 만들어져 있습니다.","price":31900,"stock":120,"specs":{"MCU":"ATmega328P","동작 전압":"5V","클럭":"16MHz","디지털 I/O":"14핀 (PWM 6)","아날로그 입력":"6핀","플래시 메모리":"32KB"},"image":"/images/products/arduino-uno-r3.jpg","source_url":"https://www.devicemart.co.kr/goods/view?no=34404","is_featured":true},{"category":"boards","slug":"arduino-uno-r4-minima","name":"아두이노 우노 R4 Minima (정품)","brand":"Arduino","summary":"Cortex-M4 기반, R3와 같은 폼팩터의 32비트 보드","description":"Renesas RA4M1(Arm Cortex-M4) 프로세서를 탑재한 UNO R4 Minima(ABX00080)입니다. UNO R3와 같은 크기와 핀 배치를 유지하면서 메모리와 클럭 속도가 늘었습니다. USB-C 포트를 사용합니다.","price":26950,"stock":60,"specs":{"MCU":"Renesas RA4M1 (Cortex-M4)","클럭":"48MHz","플래시 메모리":"256KB","SRAM":"32KB","USB":"USB-C","추가 기능":"12비트 DAC, CAN, OP AMP"},"image":"/images/products/arduino-uno-r4-minima.jpg","source_url":"https://www.devicemart.co.kr/goods/view?no=15088714","is_featured":false},{"category":"boards","slug":"arduino-uno-r4-wifi","name":"아두이노 우노 R4 WiFi (정품)","brand":"Arduino","summary":"Wi-Fi·블루투스와 12x8 LED 매트릭스를 갖춘 UNO","description":"RA4M1 메인 프로세서에 ESP32-S3 무선 모듈을 더한 UNO R4 WiFi(ABX00087)입니다. Wi-Fi와 블루투스를 지원하고 보드에 12x8 LED 매트릭스와 Qwiic 커넥터가 있습니다.","price":42130,"stock":45,"specs":{"MCU":"Renesas RA4M1 (Cortex-M4)","무선 모듈":"ESP32-S3 (Wi-Fi, Bluetooth)","플래시 메모리":"256KB","SRAM":"32KB","USB":"USB-C","온보드":"12x8 LED 매트릭스, Qwiic"},"image":"/images/products/arduino-uno-r4-wifi.jpg","source_url":"https://www.devicemart.co.kr/goods/view?no=15088648","is_featured":true},{"category":"boards","slug":"arduino-nano-compatible","name":"아두이노 나노 호환보드 (CH340)","brand":"SZH","summary":"브레드보드에 바로 꽂는 소형 나노 호환보드","description":"아두이노 나노와 호환되는 소형 보드로, USB-시리얼 칩으로 CH340을 사용합니다. 브레드보드에 직접 꽂아 쓸 수 있어 소형 프로젝트에 적합합니다. USB 케이블이 포함되어 있으며, PC에 CH340 드라이버 설치가 필요할 수 있습니다.","price":6050,"stock":200,"specs":{"MCU":"ATmega328P","USB-시리얼":"CH340","동작 전압":"5V","클럭":"16MHz","디지털 I/O":"14핀","아날로그 입력":"8핀"},"image":"/images/products/arduino-nano-compatible.jpg","source_url":"https://www.devicemart.co.kr/goods/view?no=1342039","is_featured":false},{"category":"boards","slug":"arduino-mega-2560-r3","name":"아두이노 메가 2560 R3 (정품)","brand":"Arduino","summary":"핀과 메모리가 넉넉한 대형 프로젝트용 보드","description":"ATmega2560 기반의 아두이노 정품 메가 2560 R3(A000067)입니다. 디지털 I/O 54핀과 아날로그 입력 16핀을 제공해 센서와 모터를 많이 쓰는 프로젝트에 적합합니다.","price":64900,"stock":35,"specs":{"MCU":"ATmega2560","동작 전압":"5V","클럭":"16MHz","디지털 I/O":"54핀 (PWM 15)","아날로그 입력":"16핀","플래시 메모리":"256KB"},"image":"/images/products/arduino-mega-2560-r3.jpg","source_url":"https://www.devicemart.co.kr/goods/view?no=34405","is_featured":false},{"category":"boards","slug":"esp32-devkitc-v4","name":"ESP32 DevKitC V4 개발보드 (WROOM-32D, CH9102X)","brand":"Happy House","summary":"Wi-Fi·블루투스 내장 듀얼코어 IoT 개발보드","description":"ESP32-WROOM-32D 모듈을 탑재한 DevKitC V4 호환 개발보드입니다. Wi-Fi와 블루투스를 모두 지원하며 아두이노 IDE로 프로그래밍할 수 있습니다. USB-시리얼 칩으로 CH9102X를 사용합니다.","price":8690,"stock":150,"specs":{"모듈":"ESP32-WROOM-32D","CPU":"듀얼코어 최대 240MHz","무선":"Wi-Fi 802.11 b/g/n, Bluetooth","USB":"Micro 5핀 (CH9102X)","입력 전압":"5V (USB)","로직 전압":"3.3V"},"image":"/images/products/esp32-devkitc-v4.jpg","source_url":"https://www.devicemart.co.kr/goods/view?no=15314103","is_featured":true},{"category":"sensors","slug":"hc-sr04-ultrasonic","name":"HC-SR04 초음파 거리 센서 모듈","brand":"SZH","summary":"초음파로 물체까지의 거리를 재는 센서","description":"초음파를 보내고 되돌아오는 시간으로 거리를 측정하는 모듈입니다. Trig 핀으로 펄스를 보내고 Echo 핀의 펄스 폭을 읽어 거리를 계산합니다. 장애물 감지, 거리 측정 실습에 많이 쓰입니다.","price":1210,"stock":200,"specs":{"동작 전압":"5V","측정 거리":"2cm ~ 400cm","초음파 주파수":"40kHz","핀":"VCC, Trig, Echo, GND"},"image":"/images/products/hc-sr04-ultrasonic.jpg","source_url":"https://www.devicemart.co.kr/goods/view?no=1076851","is_featured":true},{"category":"sensors","slug":"dht11-temp-humidity","name":"DHT11 온습도 센서 모듈","brand":"SZH","summary":"온도와 습도를 한 번에 읽는 디지털 센서","description":"DHT11 센서를 모듈 형태로 만든 제품으로, 단일 데이터선으로 보정된 온도·습도 값을 디지털로 출력합니다. 연결용 케이블이 포함되어 있습니다.","price":1760,"stock":180,"specs":{"측정 범위(습도)":"20 ~ 90%RH","측정 범위(온도)":"0 ~ 50°C","정확도":"±5%RH, ±2°C","동작 전압":"3.3 ~ 5V","출력":"단일 버스 디지털"},"image":"/images/products/dht11-temp-humidity.jpg","source_url":"https://www.devicemart.co.kr/goods/view?no=1278926","is_featured":false},{"category":"sensors","slug":"hc-sr501-pir","name":"HC-SR501 PIR 인체감지 센서 모듈","brand":"SZH","summary":"사람의 움직임을 감지하는 적외선 센서","description":"사람 몸에서 나오는 적외선 변화를 감지해 HIGH 신호를 출력하는 PIR 센서 모듈입니다. 보드의 가변저항으로 감지 거리와 출력 유지 시간을 조절할 수 있습니다.","price":1650,"stock":150,"specs":{"동작 전압":"DC 4.5 ~ 20V","출력":"디지털 (HIGH 3.3V)","감지 거리":"약 3 ~ 7m (조절)","감지 각도":"약 110°","조절":"감도, 지연 시간"},"image":"/images/products/hc-sr501-pir.jpg","source_url":"https://www.devicemart.co.kr/goods/view?no=1287086","is_featured":false},{"category":"sensors","slug":"soil-moisture-sensor","name":"토양 습도 센서 모듈","brand":"SZH","summary":"흙의 수분량을 측정하는 프로브형 센서","description":"두 개의 전극을 흙에 꽂아 토양의 습도를 측정하는 센서입니다. A/D 컨버터(비교기) 보드가 함께 있어 아날로그 값과 디지털 신호를 모두 사용할 수 있습니다. 화분 자동 급수 같은 실습에 쓰입니다.","price":1100,"stock":160,"specs":{"동작 전압":"3.3 ~ 5V","출력":"아날로그 + 디지털","구성":"프로브 + 비교기 보드","조절":"가변저항으로 감도 설정"},"image":"/images/products/soil-moisture-sensor.jpg","source_url":"https://www.devicemart.co.kr/goods/view?no=1376532","is_featured":false},{"category":"sensors","slug":"mpu-6050-gy-521","name":"MPU-6050 6축 자이로·가속도 센서 모듈 (GY-521)","brand":"SZH","summary":"3축 가속도와 3축 자이로를 한 칩에","description":"InvenSense MPU-6050 칩을 사용한 GY-521 모듈입니다. 3축 가속도와 3축 각속도를 I2C로 읽을 수 있어 기울기 측정, 밸런싱 로봇, 드론 실습에 쓰입니다.","price":4950,"stock":120,"specs":{"센서 칩":"MPU-6050","측정":"3축 가속도 + 3축 자이로","인터페이스":"I2C","가속도 범위":"±2/4/8/16g","자이로 범위":"±250/500/1000/2000°/s"},"image":"/images/products/mpu-6050-gy-521.jpg","source_url":"https://www.devicemart.co.kr/goods/view?no=1247052","is_featured":false},{"category":"actuators","slug":"sg90-servo","name":"SG90 9g 미니 서보모터 (호환)","brand":"SZH","summary":"정해진 각도로 움직이는 대표 미니 서보","description":"TowerPro SG90 호환 9g 미니 서보모터입니다. PWM 신호로 0~180° 범위에서 각도를 제어할 수 있어 로봇 팔, 자동 개폐 장치 실습에 많이 쓰입니다.","price":2090,"stock":200,"specs":{"무게":"9g","토크":"1.8kg·cm (4.8V)","속도":"0.1초/60° (4.8V)","회전 범위":"약 180°","동작 전압":"4.8 ~ 6V"},"image":"/images/products/sg90-servo.jpg","source_url":"https://www.devicemart.co.kr/goods/view?no=1128421","is_featured":true},{"category":"actuators","slug":"stepper-28byj-48-uln2003","name":"28BYJ-48 5V 스텝모터 + ULN2003 드라이버 세트","brand":"SZH","summary":"각도·방향·속도를 제어하는 스텝모터 입문 세트","description":"5V 28BYJ-48 스텝모터와 ULN2003 드라이버 모듈을 묶은 세트입니다. 드라이버를 통해 회전 각도, 방향, 속도를 제어할 수 있으며 360도 연속 회전이 가능합니다.","price":2310,"stock":100,"specs":{"모터":"28BYJ-48 (5V, 4상)","드라이버":"ULN2003","모터 지름":"28mm","드라이버 보드 크기":"35 x 33mm"},"image":"/images/products/stepper-28byj-48-uln2003.jpg","source_url":"https://www.devicemart.co.kr/goods/view?no=1327608","is_featured":false},{"category":"actuators","slug":"relay-module-1ch-5v","name":"1채널 5V 릴레이 모듈","brand":"SZH","summary":"아두이노로 고전압 기기를 켜고 끄는 모듈","description":"아두이노의 디지털 신호로 릴레이를 구동해 별도 전원의 기기를 켜고 끌 수 있는 1채널 모듈입니다. 상용 전원(AC)을 다룰 때는 감전에 주의해야 합니다.","price":1210,"stock":150,"specs":{"코일 전압":"5V","최대 부하":"AC 250V/10A, DC 30V/10A","채널":"1","크기":"50 x 26 x 18.5mm"},"image":"/images/products/relay-module-1ch-5v.jpg","source_url":"https://www.devicemart.co.kr/goods/view?no=1320897","is_featured":false},{"category":"actuators","slug":"l298n-motor-driver","name":"L298N 듀얼 H-브리지 모터 드라이버 모듈","brand":"SZH","summary":"DC모터 2개를 정·역회전 제어하는 드라이버","description":"ST L298N 칩을 탑재한 듀얼 H-브리지 모터 드라이버 모듈입니다. DC모터 2개 또는 스텝모터 1개의 방향과 속도를 제어할 수 있어 RC카, 로봇 실습에 많이 쓰입니다.","price":2970,"stock":120,"specs":{"드라이버 IC":"L298N","채널":"2 (H-브리지)","모터 전압":"5 ~ 35V","최대 전류":"2A (브리지당)"},"image":"/images/products/l298n-motor-driver.jpg","source_url":"https://www.devicemart.co.kr/goods/view?no=1278835","is_featured":false},{"category":"displays","slug":"lcd-1602-i2c","name":"1602 캐릭터 LCD 모듈 (I2C)","brand":"SZH","summary":"16자 2줄 문자 표시, I2C 4선 연결","description":"16x2 문자 LCD에 I2C 변환 보드가 붙어 있어 전원 2선과 SDA·SCL 2선만으로 연결할 수 있습니다. 블루 백라이트에 흰색 문자로 표시됩니다.","price":2750,"stock":150,"specs":{"표시":"16문자 x 2줄","인터페이스":"I2C","백라이트":"Blue (흰색 문자)","동작 전압":"5V","크기":"80 x 36mm"},"image":"/images/products/lcd-1602-i2c.jpg","source_url":"https://www.devicemart.co.kr/goods/view?no=1327456","is_featured":false},{"category":"displays","slug":"oled-096-ssd1306","name":"0.96인치 OLED 디스플레이 128x64 (SSD1306, I2C)","brand":"Voltly","summary":"작고 선명한 128x64 그래픽 OLED","description":"SSD1306 컨트롤러를 사용하는 0.96인치 128x64 OLED 모듈입니다. 백라이트 없이 자체 발광해 명암비가 높고, I2C로 연결해 글자와 간단한 그래픽을 표시할 수 있습니다.","price":7040,"stock":100,"specs":{"크기":"0.96인치","해상도":"128 x 64","컨트롤러":"SSD1306","인터페이스":"I2C","색상":"White"},"image":"/images/products/oled-096-ssd1306.jpg","source_url":"https://www.devicemart.co.kr/goods/view?no=15960989","is_featured":false},{"category":"displays","slug":"max7219-dot-matrix","name":"MAX7219 8x8 도트 매트릭스 모듈","brand":"SZH","summary":"LED 64개를 3선으로 제어하는 도트 매트릭스","description":"MAX7219 드라이버로 8x8 LED 도트 매트릭스를 제어하는 모듈입니다. 데이터·클럭·CS 3선으로 연결하며, 여러 개를 이어 붙여 전광판처럼 쓸 수 있습니다.","price":2420,"stock":90,"specs":{"드라이버 IC":"MAX7219","LED":"8 x 8 도트","인터페이스":"DIN, CS, CLK (직렬)","동작 전압":"5V","확장":"여러 모듈 직렬 연결 가능"},"image":"/images/products/max7219-dot-matrix.jpg","source_url":"https://www.devicemart.co.kr/goods/view?no=1287132","is_featured":false},{"category":"parts","slug":"breadboard-830","name":"브레드보드 830핀 (MB-102)","brand":"SZH","summary":"납땜 없이 회로를 꾸미는 표준 브레드보드","description":"MB-102 규격의 830핀 브레드보드입니다. 양쪽에 전원 레일이 있으며, 부품과 점퍼 와이어를 꽂아 납땜 없이 회로를 구성할 수 있습니다.","price":1540,"stock":200,"specs":{"핀 수":"830","규격":"MB-102","크기":"165 x 55 x 8.5mm","전원 레일":"양쪽 2열"},"image":"/images/products/breadboard-830.jpg","source_url":"https://www.devicemart.co.kr/goods/view?no=1322408","is_featured":false},{"category":"parts","slug":"jumper-wire-mm-40p","name":"점퍼 케이블 40P M/