트릭스, 배터리 홀더 등으로 구성된 아두이노 학습 키트입니다. 배터리는 포함되어 있지 않습니다.","price":41250,"stock":40,"specs":{"보드":"우노 R3 호환보드","주요 구성":"프로토쉴드, 1602 LCD, 도트 매트릭스, 배터리 홀더","배터리":"미포함"},"image":"/images/products/keyes-beginner-kit.jpg","source_url":"https://www.devicemart.co.kr/goods/view?no=1376694","is_featured":false}]$json$::jsonb)
  as p(category text, slug text, name text, brand text, summary text, description text, price int, stock int,
       specs jsonb, image text, source_url text, is_featured boolean)
join public.categories c on c.slug = p.category
on conflict (slug) do update set category_id = excluded.category_id, name = excluded.name, brand = excluded.brand,
  summary = excluded.summary, description = excluded.description, price = excluded.price, stock = excluded.stock,
  specs = excluded.specs, image = excluded.image, source_url = excluded.source_url, is_featured = excluded.is_featured;
